  const names={ozon:'Ozon',tiktok:'TikTok Shop',amazon:'Amazon',mercado:'Mercado Libre',temu:'Temu'};
  const labels={overview:'总览',orders:'订单',products:'商品与库存',operations:'运营测算',agent:'AI运营',exposure:'经营关联',platforms:'多平台接入',pilots:'商品试点',live:'Ozon与飞书',alerts:'提醒与经营',research:'调研与采集',creative:'创意工作室',skills:'能力库',intelligence:'全球情报',insights:'选品与评论',support:'客服',organization:'岗位与闭环',tasks:'设备与任务',connections:'连接与知识'};
  const reactHost=window.__COMMERCE_LEGACY__?.reactHost===true;
  const initialTab=window.__COMMERCE_LEGACY__?.tab||new URL(location.href).searchParams.get('tab');
  const state={tab:Object.hasOwn(labels,initialTab)?initialTab:'overview',groupVisited:{},focusTitle:false,filtersOpen:false,businessUnavailable:false,theme:'system',themeRevision:0,themeBusy:false,demo:true,platform:'all',query:'',status:'',period:'30',store:'all',market:'all',busy:false,error:null,data:null,dataScope:null,loadedAt:null,orders:[],products:[],tasks:[],reports:[],notes:[],connections:null,runtime:null};
