    window.addEventListener('message',event=>{if(event.source!==parent||event.data?.nonce!==bridgeNonce||event.data.type!=='commerce:legacy-navigate')return;if(['light','dark','system'].includes(event.data.theme))ui.applyTheme(event.data.theme);if(event.data.tab==='operations'&&['cost','stock'].includes(event.data.mode)){analysis.mode=event.data.mode;if(state.tab==='operations')paint()}if(Object.hasOwn(labels,event.data.tab))navigate(event.data.tab)});
