  function toast(message){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.role='status';n.textContent=message;document.body.appendChild(n);setTimeout(()=>n.remove(),4500)}
  let dialogPreviousFocus=null,dialogTrigger=null;
