    const usable=element=>element?.isConnected&&!element.disabled&&element.matches('button,a,input,select,textarea,[tabindex]');
    let target=usable(dialogPreviousFocus)?dialogPreviousFocus:usable(dialogTrigger?.element)?dialogTrigger.element:null;
    if(!target&&dialogPreviousFocus?.id){const current=document.getElementById(dialogPreviousFocus.id);if(usable(current))target=current}
    if(!target&&dialogTrigger?.id)target=document.getElementById(dialogTrigger.id);
    if(!target&&dialogTrigger?.keys.length)target=[...document.querySelectorAll('button')].find(button=>!button.disabled&&dialogTrigger.keys.every(([key,value])=>button.dataset[key]===value));
